cat > tmp/test_exact.py <<'PY'
import sys, random, heapq, copy
sys.path.insert(0,'/workspace/submission')
from exactcal import calibrate,valid_calibration,valid_cycle
from exactfabric import Calendar
from exactplan import envelope, compile_plan, audit, warmup
random.seed(105)
for case in range(2000):
    k=random.randint(1,8)
    biases=[random.randrange(-100,100) for _ in range(k)]
    ms=[]
    for i in range(1,k):
        a=random.randrange(i);d=biases[i]-biases[a]
        ms.append([a,i,d-random.randrange(10),d+random.randrange(10)])
    for _ in range(random.randrange(30)):
        a=random.randrange(k);b=random.randrange(k);d=biases[b]-biases[a]
        ms.append([a,b,d-random.randrange(10),d+random.randrange(10)])
    prof={'groups':k,'jitter_ps':[random.randrange(5) for _ in range(k)],'measurements':ms}
    if random.randrange(5)==0:
        prof['measurements'].append([random.randrange(k),random.randrange(k),-1000,-999])
    cert=calibrate(prof)
    if cert['status']=='inconsistent':
        assert valid_cycle(prof,cert)
        continue
    assert valid_calibration(prof,cert,cert)
    n=random.randint(1,8); p=random.randint(1,8); t=random.randint(1,10)
    # S=t*P implies declared period P, one slice, all nodes can have up to n-1 ports
    f={'n':n,'interval_ns':t,'slice_ns':p*t,'offset_ns':random.randrange(p*t),'drift_ppb':[random.randrange(5) for _ in range(n)],'heat':[],'anchors':[], 'links':[],'slices':[[]],'blackouts':[],'guards_ns':[0], 'reconfig_ns':0}
    if p*t>4:f['guards_ns'].extend([1,2])
    for _ in range(random.randrange(10)):
        a=random.randrange(n);st=random.randrange(p);en=random.randrange(st+1,p+1)
        f['heat'].append([a,st,en,random.randrange(5)])
    for _ in range(random.randrange(1,6)):
        a=random.randrange(n);st=random.randrange(p);en=random.randrange(st+1,p+1)
        f['anchors'].append([a,st,en])
    for a in range(n):
        for b in range(a+1,n):
            if random.randrange(3)==0:continue
            lid=len(f['links'])
            f['links'].append({'ends':[[a,b,0],[b,a,0]],'delay_ns':[random.randint(1,8*t),random.randint(1,8*t)],'defer_rounds':[random.randrange(9),random.randrange(9)]})
            f['slices'][0].append(lid)
            if random.randrange(3)==0:
                st=random.randrange(p);en=random.randrange(st+1,p+1)
                f['blackouts'].append([lid,st,en])
    # all link groups0 so physical group consistent
    cal=Calendar(prof,f,cert)
    for phase in range(p):
        for code,direction in enumerate(cal.directions):
            src,dst,slot,delay,flight,rounds,*_=direction
            partial=flight*t-delay
            age=partial*cal.rates[dst][(phase+flight-1)%p]
            age+=sum(cal.rates[dst][(phase+j)%p]*t for j in range(flight,rounds))
            assert age==cal.aging(phase,code)
            blocked=any(cal.black[code//2] >> ((phase+j)%p) & 1 for j in range(flight))
            assert blocked==cal.blocked(phase,code)
    for g in f['guards_ns']:
        peak,labels,pr=envelope(cal,g,True)
        dist=[None]*cal.size
        adj=[[] for _ in range(cal.size)]
        for v in range(cal.size):
            phase,i=divmod(v,n)
            adj[v].append((((phase+1)%p)*n+i,cal.rates[i][phase]*t,1))
            for code,direction in enumerate(cal.directions):
                src,dst,slot,delay,flight,rounds,hop,*_=direction
                if src==i and cal.eligible(phase,code,g):
                    adj[v].append((((phase+rounds)%p)*n+dst,hop+cal.aging(phase,code),rounds))
        h=[]
        for v in cal.sources:dist[v]=(0,0);heapq.heappush(h,(0,0,v))
        while h:
            err,age,v=heapq.heappop(h)
            if dist[v]!=(err,age):continue
            for w,e,a in adj[v]:
                cand=(err+e,age+a)
                if dist[w] is None or cand<dist[w]:
                    dist[w]=cand;heapq.heappush(h,(*cand,w))
        assert dist==[None if v is None else divmod(v,cal.radix) for v in labels]
        if peak is not None:
            # Finite-time bound relaxation and compare earliest optimal cycle
            cycle=warmup(cal,labels)
            values=[[None]*n for _ in range((cycle+2)*p+16)]
            for tick in range((cycle+2)*p):
                ph=tick%p
                for i in cal.anchor_nodes[ph]:values[tick][i]=0
                for i,err in enumerate(values[tick]):
                    if err is None:continue
                    for to,e,a in adj[ph*n+i]:
                        j=to%n;dest=tick+a
                        cand=err+e
                        old=values[dest][j]
                        if old is None or cand<old:values[dest][j]=cand
            good=[]
            for cyc in range(cycle+2):
                good.append(all(values[cyc*p+ph][i]==dist[ph*n+i][0] for ph in range(p) for i in range(n)))
            assert good[cycle] and (cycle==0 or not good[cycle-1]),(cycle,good)
    plan=compile_plan(prof,f)
    assert audit(prof,f,plan)=={'valid':True}
    if plan['guard_ns'] is not None:
        bad=copy.deepcopy(plan);bad['age_rounds'][0][0]+=1
        assert audit(prof,f,bad)=={'valid':False}
print('random calibration, periodic bounds, warmup, aging, blackouts, audit OK')
